content.code:
body {
  font-family: Arial, sans-serif;
}

h1 {
  font-size: 32px;
  font-weight: bold;
}

.card {
  width: 300px;
  padding: 20px;
  border: 2px solid black;
  margin: 10px;
}

.block {
  display: block;
}

.inline {
  display: inline;
}

.hidden {
  display: none;
}

.parent {
  position: relative;
}

.child {
  position: absolute;
  top: 10px;
  right: 10px;
}

.container {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
}
